def longest_repeated_substring_length(L, S):
    def is_repeated(length):
        seen = set()
        for i in range(L - length + 1):
            substring = S[i:i + length]
            if substring in seen:
                return True
            seen.add(substring)
        return False

    left, right = 0, L
    while left < right:
        mid = (left + right + 1) // 2
        if is_repeated(mid):
            left = mid
        else:
            right = mid - 1
    return left

# Read input
L = int(input().strip())
S = input().strip()

# Calculate and output the result
result = longest_repeated_substring_length(L, S)
print(result)
